function countDistinct(arr, k) {
  const result = [];
  for (let s = 0; s + k <= arr.length; s++) {     // every window start
    let distinct = 0;
    for (let i = s; i < s + k; i++) {
      let seenBefore = false;
      for (let j = s; j < i; j++) {
        if (arr[j] === arr[i]) { seenBefore = true; break; }   // an earlier copy in this window
      }
      if (!seenBefore) distinct++;
    }
    result.push(distinct);
  }
  return result;
}

