function countDistinct(arr, k) {
  const freq = new Map();                             // value -> count inside the window
  const result = [];
  for (let i = 0; i < arr.length; i++) {
    freq.set(arr[i], (freq.get(arr[i]) ?? 0) + 1);    // the new element comes in
    if (i >= k) {
      const out = arr[i - k];                         // the element sliding out
      freq.set(out, freq.get(out) - 1);
      if (freq.get(out) === 0) freq.delete(out);      // no copies left: drop the key
    }
    if (i >= k - 1) result.push(freq.size);           // distinct = number of keys
  }
  return result;
}

from collections import defaultdict

def count_distinct(arr, k):
    freq = defaultdict(int)                       # value -> count inside the window
    result = []
    for i, x in enumerate(arr):
        freq[x] += 1                              # the new element comes in
        if i >= k:
            out = arr[i - k]                      # the element sliding out
            freq[out] -= 1
            if freq[out] == 0:
                del freq[out]                     # no copies left: drop the key
        if i >= k - 1:
            result.append(len(freq))              # distinct = number of keys
    return result

List<Integer> countDistinct(int[] arr, int k) {
    Map<Integer, Integer> freq = new HashMap<>();        // value -> count inside the window
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < arr.length; i++) {
        freq.merge(arr[i], 1, Integer::sum);             // the new element comes in
        if (i >= k) {
            int out = arr[i - k];                        // the element sliding out
            if (freq.merge(out, -1, Integer::sum) == 0) freq.remove(out);   // no copies left: drop the key
        }
        if (i >= k - 1) result.add(freq.size());         // distinct = number of keys
    }
    return result;
}

vector<int> countDistinct(vector<int>& arr, int k) {
    unordered_map<int, int> freq;                    // value -> count inside the window
    vector<int> result;
    for (int i = 0; i < (int)arr.size(); i++) {
        freq[arr[i]]++;                              // the new element comes in
        if (i >= k) {
            int out = arr[i - k];                    // the element sliding out
            if (--freq[out] == 0) freq.erase(out);   // no copies left: drop the key
        }
        if (i >= k - 1) result.push_back(freq.size());   // distinct = number of keys
    }
    return result;
}
